std::vector<std::pair<size_t, size_t>> collisions;
for (size_t i = 0; i < boxes.size(); ++i) {
    for (size_t j = i + 1; j < boxes.size(); ++j) {
        const auto& boxA = boxes[i];
        const auto& boxB = boxes[j];

        bool overlap = true;
        for (int dim = 0; dim < 3; ++dim) {
            auto minA = OrthoTree::XYZAdaptor3D::GetBoxMinC(boxA, dim);
            auto maxA = OrthoTree::XYZAdaptor3D::GetBoxMaxC(boxA, dim);
            auto minB = OrthoTree::XYZAdaptor3D::GetBoxMinC(boxB, dim);
            auto maxB = OrthoTree::XYZAdaptor3D::GetBoxMaxC(boxB, dim);

            if (maxA < minB || maxB < minA) {
                overlap = false;
                break;
            }
        }

        if (overlap) {
            collisions.emplace_back(i, j);
        }
    }
}
return collisions;

